class Solution:
    def largest1BorderedSquare(self, grid):
        m, n = len(grid), len(grid[0])
        P = [[0] * (n + 1) for _ in range(m + 1)]
        for i in range(m):
            for j in range(n):
                P[i + 1][j + 1] = P[i][j + 1] + P[i + 1][j] - P[i][j] + grid[i][j]

        def seg(r1, c1, r2, c2):
            return P[r2 + 1][c2 + 1] - P[r1][c2 + 1] - P[r2 + 1][c1] + P[r1][c1]

        best = 0
        for r in range(m):
            for c in range(n):
                for s in range(min(m - r, n - c), best_s := 0, -1) if False else range(min(m - r, n - c), 0, -1):
                    if seg(r, c, r, c + s - 1) == s and seg(r + s - 1, c, r + s - 1, c + s - 1) == s \
                       and seg(r, c, r + s - 1, c) == s and seg(r, c + s - 1, r + s - 1, c + s - 1) == s:
                        best = max(best, s)
                        break
        return best * best

