class Solution {
public:
    int largest1BorderedSquare(vector<vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        vector<vector<int>> P(m + 1, vector<int>(n + 1, 0));
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                P[i + 1][j + 1] = P[i][j + 1] + P[i + 1][j] - P[i][j] + grid[i][j];
        auto seg = [&](int r1, int c1, int r2, int c2) {
            return P[r2 + 1][c2 + 1] - P[r1][c2 + 1] - P[r2 + 1][c1] + P[r1][c1];
        };
        int best = 0;
        for (int r = 0; r < m; r++)
            for (int c = 0; c < n; c++)
                for (int s = min(m - r, n - c); s > best; s--)
                    if (seg(r, c, r, c + s - 1) == s && seg(r + s - 1, c, r + s - 1, c + s - 1) == s &&
                        seg(r, c, r + s - 1, c) == s && seg(r, c + s - 1, r + s - 1, c + s - 1) == s)
                        { best = s; break; }
        return best * best;
    }
};

