class Solution {
    public int largest1BorderedSquare(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        int[][] P = new int[m + 1][n + 1];
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                P[i + 1][j + 1] = P[i][j + 1] + P[i + 1][j] - P[i][j] + grid[i][j];
        int best = 0;
        for (int r = 0; r < m; r++)
            for (int c = 0; c < n; c++)
                for (int s = Math.min(m - r, n - c); s > best; s--) {
                    boolean ok = sum(P, r, c, r, c + s - 1) == s
                              && sum(P, r + s - 1, c, r + s - 1, c + s - 1) == s
                              && sum(P, r, c, r + s - 1, c) == s
                              && sum(P, r, c + s - 1, r + s - 1, c + s - 1) == s;
                    if (ok) { best = s; break; }
                }
        return best * best;
    }
    private int sum(int[][] P, int r1, int c1, int r2, int c2) {
        return P[r2 + 1][c2 + 1] - P[r1][c2 + 1] - P[r2 + 1][c1] + P[r1][c1];
    }
}

