class Solution:
    def largest1BorderedSquare(self, grid):
        m, n = len(grid), len(grid[0])
        left = [[0] * n for _ in range(m)]
        up = [[0] * n for _ in range(m)]
        for i in range(m):
            for j in range(n):
                if grid[i][j]:
                    left[i][j] = (left[i][j - 1] if j else 0) + 1
                    up[i][j] = (up[i - 1][j] if i else 0) + 1
        best = 0
        for i in range(m):
            for j in range(n):
                for s in range(min(left[i][j], up[i][j]), best, -1):
                    if left[i - s + 1][j] >= s and up[i][j - s + 1] >= s:
                        best = s
                        break
        return best * best

